onClick:
{{
  (async () => {
    try {
      const motivo = String(
        inpDirUpdateMotivo.text || ""
      ).trim();

      const password = String(
        inpDirUpdatePassword.text || ""
      ).trim();

      const context =
        appsmith.store.cp_update_context || {};

      const entity =
        context.entity || null;

      const mode =
        context.mode || "UPDATE";

      const tenantId =
        appsmith.store.cp_tenant_id ||
        appsmith.store.tenant_id ||
        appsmith.store.current_user?.tenant_id ||
        null;

      const userId =
        appsmith.store.user_id ||
        appsmith.store.current_user?.id ||
        null;

      /*
       * =========================================================
       * 1. VALIDACIÓN GENERAL DEL CONTEXTO
       * =========================================================
       */

      if (!entity) {
        showAlert(
          "NO HAY CONTEXTO DE CREACIÓN O ACTUALIZACIÓN.",
          "error"
        );
        return false;
      }

      if (
        !["CREATE", "UPDATE"].includes(mode)
      ) {
        showAlert(
          "EL MODAL NO ESTÁ EN UN MODO VÁLIDO.",
          "error"
        );
        return false;
      }

      if (!tenantId) {
        showAlert(
          "NO SE ENCONTRÓ EL TENANT DEL USUARIO O DE LA OPERACIÓN.",
          "error"
        );
        return false;
      }

      if (!userId) {
        showAlert(
          "NO SE ENCONTRÓ EL USUARIO AUTENTICADO.",
          "error"
        );
        return false;
      }

      if (
        mode === "UPDATE" &&
        !context.entity_id
      ) {
        showAlert(
          "NO SE ENCONTRÓ EL REGISTRO QUE SE DESEA ACTUALIZAR.",
          "error"
        );
        return false;
      }

      if (
        entity === "CONDUCTOR" &&
        mode === "UPDATE" &&
        !context.tenant_conductor_id
      ) {
        showAlert(
          "NO SE ENCONTRÓ LA RELACIÓN TENANT DEL CONDUCTOR.",
          "error"
        );
        return false;
      }

      if (
        entity === "VEHICULO" &&
        mode === "UPDATE" &&
        !context.tenant_vehiculo_id
      ) {
        showAlert(
          "NO SE ENCONTRÓ LA RELACIÓN TENANT DEL VEHÍCULO.",
          "error"
        );
        return false;
      }

      if (!motivo) {
        showAlert(
          mode === "CREATE"
            ? "DEBE INGRESAR EL MOTIVO DE CREACIÓN."
            : "DEBE INGRESAR EL MOTIVO DE ACTUALIZACIÓN.",
          "warning"
        );
        return false;
      }

      if (!password) {
        showAlert(
          "DEBE INGRESAR LA CONTRASEÑA.",
          "warning"
        );
        return false;
      }

      /*
       * =========================================================
       * 2. VALIDACIONES DEL CONDUCTOR
       * =========================================================
       */

      if (entity === "CONDUCTOR") {
        if (
          !slDirCondTipoDocumento
            .selectedOptionValue
        ) {
          showAlert(
            "EL TIPO DE DOCUMENTO ES OBLIGATORIO.",
            "warning"
          );
          return false;
        }

        if (
          !String(
            inpDirCondNombre.text || ""
          ).trim()
        ) {
          showAlert(
            "EL NOMBRE DEL CONDUCTOR ES OBLIGATORIO.",
            "warning"
          );
          return false;
        }

        if (
          !String(
            inpDirCondDocumento.text || ""
          ).trim()
        ) {
          showAlert(
            "EL DOCUMENTO DEL CONDUCTOR ES OBLIGATORIO.",
            "warning"
          );
          return false;
        }

        if (
          !String(
            inpDirCondLicencia.text || ""
          ).trim()
        ) {
          showAlert(
            "LA LICENCIA DEL CONDUCTOR ES OBLIGATORIA.",
            "warning"
          );
          return false;
        }

        if (
          !Array.isArray(
            msDirCondCategoriaLicencia
              .selectedOptionValues
          ) ||
          msDirCondCategoriaLicencia
            .selectedOptionValues.length === 0
        ) {
          showAlert(
            "LA CATEGORÍA DE LICENCIA ES OBLIGATORIA.",
            "warning"
          );
          return false;
        }

        if (
          !dpDirCondVencimientoLicencia
            .selectedDate
        ) {
          showAlert(
            "LA FECHA DE VENCIMIENTO DE LA LICENCIA ES OBLIGATORIA.",
            "warning"
          );
          return false;
        }

        if (
          !String(
            inpDirCondTelefono.text || ""
          ).trim()
        ) {
          showAlert(
            "EL TELÉFONO DEL CONDUCTOR ES OBLIGATORIO.",
            "warning"
          );
          return false;
        }

        if (
          !String(
            inpDirCondEmail.text || ""
          ).trim()
        ) {
          showAlert(
            "EL CORREO DEL CONDUCTOR ES OBLIGATORIO.",
            "warning"
          );
          return false;
        }
      }

      /*
       * =========================================================
       * 3. VALIDACIONES DEL VEHÍCULO
       * =========================================================
       */

      if (entity === "VEHICULO") {
        if (
          !String(
            inpDirVehPlaca.text || ""
          ).trim()
        ) {
          showAlert(
            "LA PLACA DEL VEHÍCULO ES OBLIGATORIA.",
            "warning"
          );
          return false;
        }

        if (
          !slDirVehTipoVehiculo
            .selectedOptionValue
        ) {
          showAlert(
            "EL TIPO DE VEHÍCULO ES OBLIGATORIO.",
            "warning"
          );
          return false;
        }

        if (
          !slDirVehMarca.selectedOptionValue
        ) {
          showAlert(
            "LA MARCA DEL VEHÍCULO ES OBLIGATORIA.",
            "warning"
          );
          return false;
        }

        if (
          !String(
            inpDirVehModelo.text || ""
          ).trim()
        ) {
          showAlert(
            "EL MODELO DEL VEHÍCULO ES OBLIGATORIO.",
            "warning"
          );
          return false;
        }

        if (
          !slDirVehColor.selectedOptionValue
        ) {
          showAlert(
            "EL COLOR DEL VEHÍCULO ES OBLIGATORIO.",
            "warning"
          );
          return false;
        }

        const capacidadKg = Number(
          String(
            inpDirVehCapacidadKg.text || ""
          )
            .trim()
            .replace(",", ".")
        );

        if (
          !Number.isFinite(capacidadKg) ||
          capacidadKg <= 0
        ) {
          showAlert(
            "LA CAPACIDAD DE CARGA DEBE SER MAYOR QUE CERO.",
            "warning"
          );
          return false;
        }

        if (
          !String(
            inpDirVehSoatNo.text || ""
          ).trim()
        ) {
          showAlert(
            "EL NÚMERO DE SOAT ES OBLIGATORIO.",
            "warning"
          );
          return false;
        }

        if (
          !dpDirVehSoatVencimiento
            .selectedDate
        ) {
          showAlert(
            "LA FECHA DE VENCIMIENTO DEL SOAT ES OBLIGATORIA.",
            "warning"
          );
          return false;
        }
      }

      /*
       * =========================================================
       * 4. AUTORIZACIÓN DEL USUARIO
       * =========================================================
       */

      await qDirAuthUsuario.run();

      const authUser =
        qDirAuthUsuario.data?.[0] || null;

      if (!authUser?.id) {
        showAlert(
          "CONTRASEÑA INCORRECTA O USUARIO SIN PERMISO.",
          "error"
        );
        return false;
      }

      /*
       * =========================================================
       * 5. CREAR O ACTUALIZAR CONDUCTOR
       * =========================================================
       */

      if (entity === "CONDUCTOR") {
        /*
         * ---------------------------------------------------------
         * 5.1 CREAR CONDUCTOR
         * ---------------------------------------------------------
         */

        if (mode === "CREATE") {
          await bkDirCrearConductor.run();

          const createdConductor =
            bkDirCrearConductor.data?.[0] ||
            null;

          if (
            !createdConductor?.conductor_id ||
            !createdConductor
              ?.tenant_conductor_id
          ) {
            showAlert(
              "LA QUERY FINALIZÓ, PERO NO DEVOLVIÓ LA IDENTIDAD Y LA RELACIÓN TENANT DEL CONDUCTOR.",
              "error"
            );
            return false;
          }

          await storeValue(
            "cp_update_context",
            {
              ...context,

              entity: "CONDUCTOR",
              mode: "CREATE",

              entity_id:
                createdConductor
                  .conductor_id,

              tenant_conductor_id:
                createdConductor
                  .tenant_conductor_id
            }
          );

          await qCpBuscarConductorPorDocumento
            .run();

          const foundConductor =
            qCpBuscarConductorPorDocumento
              .data?.[0] || null;

          if (
            !foundConductor?.conductor_id ||
            !foundConductor
              ?.tenant_conductor_id
          ) {
            showAlert(
              "EL CONDUCTOR FUE CREADO, PERO NO PUDO SER RECUPERADO DESDE EL DIRECTORIO DEL TENANT.",
              "warning"
            );
            return false;
          }

          const syncOk =
            await JS_CarguePlanta
              .syncConductorDirectorioToForm();

          if (!syncOk) {
            showAlert(
              "EL CONDUCTOR FUE CREADO, PERO NO SE PUDO CARGAR EN EL FORMULARIO DEL VIAJE.",
              "warning"
            );
            return false;
          }

          closeModal(
            "mdlDirectorioUpdate"
          );

          await JS_CarguePlanta
            .clearDirectorioUpdateModal();

          showAlert(
            "CONDUCTOR CREADO CORRECTAMENTE Y CARGADO EN EL FORMULARIO DEL VIAJE.",
            "success"
          );

          return true;
        }

        /*
         * ---------------------------------------------------------
         * 5.2 ACTUALIZAR CONDUCTOR
         * ---------------------------------------------------------
         */

        if (mode === "UPDATE") {
          await bkDirActualizarConductor
            .run();

          const updatedConductor =
            bkDirActualizarConductor
              .data?.[0] || null;

          if (
            !updatedConductor?.conductor_id ||
            !updatedConductor
              ?.tenant_conductor_id
          ) {
            showAlert(
              "LA QUERY FINALIZÓ, PERO NO DEVOLVIÓ LA IDENTIDAD Y LA RELACIÓN TENANT DEL CONDUCTOR ACTUALIZADO.",
              "error"
            );
            return false;
          }

          if (
            updatedConductor.conductor_id !==
            context.entity_id
          ) {
            showAlert(
              "LA IDENTIDAD ACTUALIZADA NO COINCIDE CON EL CONDUCTOR ABIERTO EN EL MODAL.",
              "error"
            );
            return false;
          }

          if (
            updatedConductor
              .tenant_conductor_id !==
            context.tenant_conductor_id
          ) {
            showAlert(
              "LA RELACIÓN TENANT ACTUALIZADA NO COINCIDE CON EL CONDUCTOR ABIERTO EN EL MODAL.",
              "error"
            );
            return false;
          }

          await qCpBuscarConductorPorDocumento
            .run();

          const foundConductor =
            qCpBuscarConductorPorDocumento
              .data?.[0] || null;

          if (
            !foundConductor?.conductor_id ||
            !foundConductor
              ?.tenant_conductor_id
          ) {
            showAlert(
              "EL CONDUCTOR FUE ACTUALIZADO, PERO NO PUDO SER RECUPERADO DESDE EL DIRECTORIO DEL TENANT.",
              "warning"
            );
            return false;
          }

          const syncOk =
            await JS_CarguePlanta
              .syncConductorDirectorioToForm();

          if (!syncOk) {
            showAlert(
              "EL CONDUCTOR SE ACTUALIZÓ EN EL DIRECTORIO, PERO NO SE PUDO SINCRONIZAR CON EL FORMULARIO DEL VIAJE.",
              "warning"
            );
            return false;
          }

          closeModal(
            "mdlDirectorioUpdate"
          );

          await JS_CarguePlanta
            .clearDirectorioUpdateModal();

          showAlert(
            "CONDUCTOR ACTUALIZADO. LOS DATOS NUEVOS FUERON CARGADOS EN EL FORMULARIO; PULSE GUARDAR VIAJE PARA CONFIRMARLOS.",
            "success"
          );

          return true;
        }
      }

      /*
       * =========================================================
       * 6. CREAR O ACTUALIZAR VEHÍCULO
       * =========================================================
       */

      if (entity === "VEHICULO") {
        /*
         * ---------------------------------------------------------
         * 6.1 CREAR VEHÍCULO
         * ---------------------------------------------------------
         */

        if (mode === "CREATE") {
          await bkDirCrearVehiculo.run();

          const createdVehiculo =
            bkDirCrearVehiculo.data?.[0] ||
            null;

          if (
            !createdVehiculo?.vehiculo_id ||
            !createdVehiculo
              ?.tenant_vehiculo_id
          ) {
            showAlert(
              "LA QUERY FINALIZÓ, PERO NO DEVOLVIÓ LA IDENTIDAD Y LA RELACIÓN TENANT DEL VEHÍCULO.",
              "error"
            );
            return false;
          }

          /*
           * Conservamos los identificadores de las dos capas
           * durante el resto del flujo.
           */
          await storeValue(
            "cp_update_context",
            {
              ...context,

              entity: "VEHICULO",
              mode: "CREATE",

              entity_id:
                createdVehiculo.vehiculo_id,

              tenant_vehiculo_id:
                createdVehiculo
                  .tenant_vehiculo_id
            }
          );

          /*
           * Recuperamos el vehículo por la placa que permanece
           * diligenciada en el formulario principal.
           */
          await qCpBuscarVehiculoPorPlaca
            .run();

          const foundVehiculo =
            qCpBuscarVehiculoPorPlaca
              .data?.[0] || null;

          if (
            !foundVehiculo?.vehiculo_id ||
            !foundVehiculo
              ?.tenant_vehiculo_id
          ) {
            showAlert(
              "EL VEHÍCULO FUE CREADO, PERO NO PUDO SER RECUPERADO DESDE EL DIRECTORIO DEL TENANT.",
              "warning"
            );
            return false;
          }

          /*
           * Comprobamos que la búsqueda recuperó exactamente
           * el vehículo recién creado.
           */
          if (
            foundVehiculo.vehiculo_id !==
              createdVehiculo.vehiculo_id ||
            foundVehiculo
              .tenant_vehiculo_id !==
              createdVehiculo
                .tenant_vehiculo_id
          ) {
            showAlert(
              "EL VEHÍCULO FUE CREADO, PERO LA BÚSQUEDA POSTERIOR DEVOLVIÓ UN REGISTRO DIFERENTE.",
              "error"
            );
            return false;
          }

          const syncOk =
            await JS_CarguePlanta
              .syncVehiculoDirectorioToForm();

          if (!syncOk) {
            showAlert(
              "EL VEHÍCULO FUE CREADO, PERO NO SE PUDO CARGAR EN EL FORMULARIO DEL VIAJE.",
              "warning"
            );
            return false;
          }

          closeModal(
            "mdlDirectorioUpdate"
          );

          await JS_CarguePlanta
            .clearDirectorioUpdateModal();

          showAlert(
            "VEHÍCULO CREADO CORRECTAMENTE Y CARGADO EN EL FORMULARIO DEL VIAJE.",
            "success"
          );

          return true;
        }

        /*
         * ---------------------------------------------------------
         * 6.2 ACTUALIZAR VEHÍCULO
         * ---------------------------------------------------------
         */

        if (mode === "UPDATE") {
          await bkDirActualizarVehiculo
            .run();

          const updatedVehiculo =
            bkDirActualizarVehiculo
              .data?.[0] || null;

          if (
            !updatedVehiculo?.vehiculo_id ||
            !updatedVehiculo
              ?.tenant_vehiculo_id
          ) {
            showAlert(
              "LA QUERY FINALIZÓ, PERO NO DEVOLVIÓ LA IDENTIDAD Y LA RELACIÓN TENANT DEL VEHÍCULO ACTUALIZADO.",
              "error"
            );
            return false;
          }

          /*
           * Verificamos que la identidad actualizada sea
           * exactamente la que estaba abierta en el modal.
           */
          if (
            updatedVehiculo.vehiculo_id !==
            context.entity_id
          ) {
            showAlert(
              "LA IDENTIDAD ACTUALIZADA NO COINCIDE CON EL VEHÍCULO ABIERTO EN EL MODAL.",
              "error"
            );
            return false;
          }

          /*
           * Verificamos también la relación operativa del tenant.
           */
          if (
            updatedVehiculo
              .tenant_vehiculo_id !==
            context.tenant_vehiculo_id
          ) {
            showAlert(
              "LA RELACIÓN TENANT ACTUALIZADA NO COINCIDE CON EL VEHÍCULO ABIERTO EN EL MODAL.",
              "error"
            );
            return false;
          }

          await qCpBuscarVehiculoPorPlaca
            .run();

          const foundVehiculo =
            qCpBuscarVehiculoPorPlaca
              .data?.[0] || null;

          if (
            !foundVehiculo?.vehiculo_id ||
            !foundVehiculo
              ?.tenant_vehiculo_id
          ) {
            showAlert(
              "EL VEHÍCULO FUE ACTUALIZADO, PERO NO PUDO SER RECUPERADO DESDE EL DIRECTORIO DEL TENANT.",
              "warning"
            );
            return false;
          }

          /*
           * Confirmamos que la búsqueda posterior conserva
           * la identidad y la relación tenant actualizadas.
           */
          if (
            foundVehiculo.vehiculo_id !==
              updatedVehiculo.vehiculo_id ||
            foundVehiculo
              .tenant_vehiculo_id !==
              updatedVehiculo
                .tenant_vehiculo_id
          ) {
            showAlert(
              "EL VEHÍCULO FUE ACTUALIZADO, PERO LA BÚSQUEDA POSTERIOR DEVOLVIÓ UN REGISTRO DIFERENTE.",
              "error"
            );
            return false;
          }

          const syncOk =
            await JS_CarguePlanta
              .syncVehiculoDirectorioToForm();

          if (!syncOk) {
            showAlert(
              "EL VEHÍCULO SE ACTUALIZÓ EN EL DIRECTORIO, PERO NO SE PUDO SINCRONIZAR CON EL FORMULARIO DEL VIAJE.",
              "warning"
            );
            return false;
          }

          closeModal(
            "mdlDirectorioUpdate"
          );

          await JS_CarguePlanta
            .clearDirectorioUpdateModal();

          showAlert(
            "VEHÍCULO ACTUALIZADO. LOS DATOS NUEVOS FUERON CARGADOS EN EL FORMULARIO; PULSE GUARDAR VIAJE PARA CONFIRMARLOS.",
            "success"
          );

          return true;
        }
      }

      showAlert(
        "EL CONTEXTO DEL MODAL NO CORRESPONDE A UNA OPERACIÓN VÁLIDA.",
        "error"
      );

      return false;
    } catch (error) {
      console.error(
        "ERROR btnDirGuardar:",
        error
      );

      const mensaje =
        error?.message ||
        error?.error ||
        "ERROR NO IDENTIFICADO AL GUARDAR EL DIRECTORIO.";

      showAlert(
        "NO SE PUDO COMPLETAR LA OPERACIÓN: " +
          mensaje,
        "error"
      );

      return false;
    }
  })()
}}
